@extends('layouts.app')@section('title','Invoice')@section('content')<h1>{{ isset($invoice)?'Edit invoice':'New invoice' }}</h1><div class='card form-card'><form method='post' action='{{ isset($invoice)?route('invoices.update',$invoice):route('invoices.store') }}'>@csrf @if(isset($invoice))@method('put')@endif<div class='field'><label>Invoice number</label><input name='number' value='{{ old('number',$invoice->number ?? '') }}' required></div><div class='field'><label>Client</label><select name='client_id' required><option value=''>Choose client</option>@foreach($clients as $client)<option value='{{ $client->id }}' @selected(old('client_id',$invoice->client_id ?? '')==$client->id)>{{ $client->name }}</option>@endforeach</select></div><div class='field'><label>Issue date</label><input type='date' name='issue_date' value='{{ old('issue_date',isset($invoice)?$invoice->issue_date->format('Y-m-d'):now()->format('Y-m-d')) }}'></div><div class='field'><label>Due date</label><input type='date' name='due_date' value='{{ old('due_date',isset($invoice)&&$invoice->due_date?$invoice->due_date->format('Y-m-d'):'') }}'></div><div class='field'><label>Amount</label><input type='number' step='0.01' min='0' name='amount' value='{{ old('amount',$invoice->amount ?? '') }}'></div><div class='field'><label>Currency</label><input name='currency' maxlength='3' value='{{ old('currency',$invoice->currency ?? 'USD') }}'></div><div class='field'><label>Status</label><select name='status'>@foreach(['draft','sent','paid','overdue'] as $s)<option value='{{ $s }}' @selected(old('status',$invoice->status ?? 'draft')===$s)>{{ ucfirst($s) }}</option>@endforeach</select></div><button class='btn'>Save invoice</button></form></div>@endsection